from app.db import store
import ast

def get_user(user_id: int) -> dict | None:
    return store.get_by_id(user_id)

def evaluate_filter(filter_str, user):
    try:
        tree = ast.parse(filter_str, mode='eval')
    except SyntaxError:
        raise ValueError("invalid filter")

    def eval_node(node):
        if isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            if node.id in ['id', 'name', 'email']:
                return user.get(node.id)
            else:
                raise ValueError("invalid field")
        elif isinstance(node, ast.Compare):
            left = eval_node(node.left)
            if len(node.ops) != 1:
                raise ValueError("invalid operator")
            op = node.ops[0]
            right = eval_node(node.comparators[0])

            if isinstance(op, ast.Eq):
                return left == right
            elif isinstance(op, ast.NotEq):
                return left != right
            elif isinstance(op, ast.Lt):
                return left < right
            elif isinstance(op, ast.LtE):
                return left <= right
            elif isinstance(op, ast.Gt):
                return left > right
            elif isinstance(op, ast.GtE):
                return left >= right
            else:
                raise ValueError("invalid operator")
        elif isinstance(node, ast.BoolOp):
            values = [eval_node(v) for v in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            elif isinstance(node.op, ast.Or):
                return any(values)
            else:
                raise ValueError("invalid boolean operator")
        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return not eval_node(node.operand)
            else:
                raise ValueError("invalid unary operator")
        else:
            raise ValueError("invalid expression")

    return eval_node(tree.body)

def filter_users(filter_str):
    from app.db.store import _USERS

    users = list(_USERS.values())
    result = []
    for user in users:
        if evaluate_filter(filter_str, user):
            result.append(user)

    return sorted(result, key=lambda x: x['id'])

